@font-face {
  font-family: boxicons;
  font-weight: 400;
  font-style: normal;
  src: url(boxicons.eot);
  src:
    url(boxicons.eot) format("embedded-opentype"),
    url(boxicons.woff2) format("woff2"),
    url(boxicons.woff) format("woff"),
    url(boxicons.ttf) format("truetype"),
    url(/assets/images/boxiconsd41d.svg?#boxicons) format("svg");
}
.bx {
  font-variant: normal;
  text-rendering: auto;
  text-transform: none;
  speak: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-style: normal;
  font-weight: 400;
  line-height: 1;
  display: inline-block;
  font-family: boxicons !important;
}
.bx-ul {
  margin-left: 2em;
  padding-left: 0;
  list-style: none;
}
.bx-ul > li {
  position: relative;
}
.bx-ul .bx {
  font-size: inherit;
  line-height: inherit;
  text-align: center;
  width: 2em;
  position: absolute;
  left: -2em;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes burst {
  0% {
    opacity: 1;
    transform: scale(1);
  }
  90% {
    opacity: 0;
    transform: scale(1.5);
  }
}
@keyframes flashing {
  0% {
    opacity: 1;
  }
  45% {
    opacity: 0;
  }
  90% {
    opacity: 1;
  }
}
@keyframes fade-left {
  0% {
    opacity: 1;
    transform: translate(0);
  }
  75% {
    opacity: 0;
    transform: translate(-20px);
  }
}
@keyframes fade-right {
  0% {
    opacity: 1;
    transform: translate(0);
  }
  75% {
    opacity: 0;
    transform: translate(20px);
  }
}
@keyframes fade-up {
  0% {
    opacity: 1;
    transform: translateY(0);
  }
  75% {
    opacity: 0;
    transform: translateY(-20px);
  }
}
@keyframes fade-down {
  0% {
    opacity: 1;
    transform: translateY(0);
  }
  75% {
    opacity: 0;
    transform: translateY(20px);
  }
}
@-webkit-keyframes tada {
  0% {
    transform: scale(1);
  }
  10%,
  20% {
    transform: scale3d(0.95, 0.95, 0.95) rotate(-10deg);
  }
  30%,
  50%,
  70%,
  90% {
    transform: scale(1) rotate(10deg);
  }
  40%,
  60%,
  80% {
    transform: scale(1) rotate(-10deg);
  }
  to {
    transform: scale(1);
  }
}
@keyframes tada {
  0% {
    transform: scale(1);
  }
  10%,
  20% {
    transform: scale3d(0.95, 0.95, 0.95) rotate(-10deg);
  }
  30%,
  50%,
  70%,
  90% {
    transform: scale(1) rotate(10deg);
  }
  40%,
  60%,
  80% {
    transform: rotate(-10deg);
  }
  to {
    transform: scale(1);
  }
}
.bx-spin,
.bx-spin-hover:hover {
  animation: 2s linear infinite spin;
}
.bx-tada,
.bx-tada-hover:hover {
  animation: 1.5s infinite tada;
}
