.blog-card .animate-shine {
  background: linear-gradient(
    to right,
    rgba(var(--dx-black-rgb), 0) 0,
    rgba(var(--dx-white-rgb), 0.8) 50%,
    rgba(var(--dx-black-rgb), 0) 100%
  );
  opacity: 0;
  width: 100%;
  height: 100%;
  animation: 0.75s linear shine;
  display: none;
  position: absolute;
  top: 0;
  left: 0;
  transform: skew(30deg);
}
.blog-card:hover .animate-shine {
  display: block;
}
.blog-card .entry-list:before,
.blog-card .entry-list:after {
  content: "";
  background: radial-gradient(
    circle at left top,
    transparent 15px,
    color-mix(in srgb, var(--dx-body-color) 5%, white 95%) 16px
  );
  width: 18px;
  height: 18px;
}
.blog-card .entry-list:before {
  position: absolute;
  bottom: -2.5px;
  left: -15px;
}
.blog-card .entry-list:after {
  position: absolute;
  top: -16px;
  right: -1.5px;
}
@keyframes shine {
  0% {
    opacity: 0;
    left: -50%;
  }
  50% {
    opacity: 0.5;
    left: 25%;
  }
  to {
    opacity: 0;
    left: 100%;
  }
}
